SELECT ?stopReasonLabel (COUNT(DISTINCT ?g) AS ?eventCount) WHERE {
  GRAPH ?g {
    ?r a sphn:DrugAdministrationEvent .
    ?r sphn:hasReasonToStopCode ?c
  }
  GRAPH <https://biomedit.ch/rdf/sphn-resource/global> {
    ?c rdfs:label ?stopReasonLabel
  }
}
GROUP BY ?stopReasonLabel
ORDER BY DESC(?eventCount)
LIMIT 10

SELECT (COUNT(DISTINCT ?g) AS ?count) WHERE {
  GRAPH ?g {
    ?r a sphn:Circumference .
    ?r sphn:hasQuantity ?q .
    ?q sphn:hasValue ?v .
  }
}

SELECT COUNT(DISTINCT ?g) {
  GRAPH ?g {
    ?sex a sphn:AdministrativeSex ;
         sphn:hasCode snomed:248153007 .

    ?drug a sphn:DrugAdministrationEvent .
    ?drug sphn:hasAdministrationRouteCode snomed:766790006 .
  }
}
